struct view { const char *type; void *state; const struct view_ops *ops; };
static struct view views[MAX_VIEWS]; static size_t n_views;   /* 1-based handles */
int view_open(const char *type, void *model) {
    const struct view_ops *ops = factory_for(type);      /* prototype table */
    struct view *v = &views[++n_views];
    v->type = type; v->ops = ops; v->state = ops->create(model);
    return (int)n_views;                              /* handle, not pointer */
}
void view_close(int h) { views[h].ops->destroy(views[h].state); views[h].ops = NULL; }
void view_notify_all(void) {          /* model change -> every view still alive */
    for (size_t i = 1; i <= n_views; i++) if (views[i].ops) views[i].ops->refresh(views[i].state);
}
